create or replace function operations_private.hub_product_price_read_v1(p_product text)
returns jsonb language plpgsql stable set search_path=pg_catalog as $$
declare input jsonb; stored operations_private.hub_product_price_results%rowtype; status text; history jsonb;
begin
 input:=operations_private.hub_product_price_inputs_v1(p_product);
 select r.* into stored from operations_private.hub_product_price_result_heads h join operations_private.hub_product_price_results r on r.id=h.result_id where h.product_code=p_product;
 if stored.id is not null then history:=to_jsonb(stored);end if;
 status:=case when input->'rule'='null'::jsonb then 'inactive'
  when jsonb_array_length(input->'issues')>0 then case when not exists(select 1 from jsonb_array_elements(input->'issues') i where i->>'reason' not in ('stale','proof')) then 'stale' else 'blocked' end
  when stored.id is null then 'stale' when stored.input_fingerprint<>input->>'input_fingerprint' then 'stale' else stored.status end;
 return input||jsonb_build_object('status',status,'freshness',case when status='calculated' then 'fresh' else status end,
 'value',case when status='calculated' then stored.value end,'generation_id',stored.generation_id,
 'selected_options',case when status='calculated' then stored.proof->'selected_options' else '[]'::jsonb end,
 'stored_history',history,'stored_assignment',(select to_jsonb(a) from operations_private.hub_product_price_assignments a where a.product_code=p_product),'stage','representative_price','scope','product','output_field','representative_base_price','exclusive_group','representative_price_rule');
end $$;
